//! Immutable generated bytes, kept out of diagnostics and persisted metadata.

use std::collections::BTreeMap;
use std::path::{Component, Path, PathBuf};
use std::sync::Arc;

use anyhow::{Context as _, Result, ensure};

use crate::exec::{Context, templates};
use crate::overlays::Overlay;

#[derive(Clone)]
pub struct RenderedFile {
    pub protection: crate::crypt::protection::Protection,
    pub source_revision: Option<String>,
    pub source: PathBuf,
    pub bytes: Arc<[u8]>,
    pub identity: String,
    pub mode: i32,
    pub generated: bool,
    pub permissions: Option<crate::overlays::FileMode>,
}

impl std::fmt::Debug for RenderedFile {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("RenderedFile")
            .field("source", &self.source)
            .field("identity", &self.identity)
            .field("mode", &self.mode)
            .field("generated", &self.generated)
            .finish_non_exhaustive()
    }
}

pub type RenderedInventory = BTreeMap<PathBuf, RenderedFile>;

#[derive(Debug, Clone)]
pub struct RenderedCheckout {
    pub inventory: RenderedInventory,
    pub source_revision: String,
}

impl std::ops::Deref for RenderedCheckout {
    type Target = RenderedInventory;
    fn deref(&self) -> &Self::Target {
        &self.inventory
    }
}

pub(crate) fn validate_destination(file: &RenderedFile, target: &Path) -> Result<()> {
    let destination = crate::overlays::mapping::location(target)?;
    ensure!(
        destination != crate::overlays::mapping::location(&file.source)?,
        "rendered destination '{}' would overwrite its source template '{}'",
        target.display(),
        file.source.display()
    );
    let Some(parent) = file.source.parent() else {
        return Ok(());
    };
    let repo = match git2::Repository::discover(parent) {
        Ok(repo) => repo,
        Err(error) if error.code() == git2::ErrorCode::NotFound => return Ok(()),
        Err(error) => return Err(error.into()),
    };
    if let Some(root) = repo.workdir()
        && let Ok(relative) = destination.strip_prefix(crate::overlays::mapping::physical(root)?)
    {
        ensure!(
            !relative.as_os_str().is_empty(),
            "rendered destination cannot replace the source repository root"
        );
        let index = repo.index()?;
        let indexed = (0..=3).any(|stage| index.get_path(relative, stage).is_some());
        let committed = match repo.head() {
            Ok(head) => match head.peel_to_tree()?.get_path(relative) {
                Ok(_) => true,
                Err(error) if error.code() == git2::ErrorCode::NotFound => false,
                Err(error) => return Err(error.into()),
            },
            Err(error)
                if matches!(
                    error.code(),
                    git2::ErrorCode::UnbornBranch | git2::ErrorCode::NotFound
                ) =>
            {
                false
            }
            Err(error) => return Err(error.into()),
        };
        ensure!(
            !indexed && !committed,
            "rendered destination '{}' would overwrite tracked source content (source template '{}')",
            target.display(),
            file.source.display()
        );
    }
    Ok(())
}

pub(crate) fn validate_ingestion(
    ctx: &Context,
    overlay: &Overlay,
    selections: &[PathBuf],
) -> Result<()> {
    let tree = super::DesiredTree::build_own(ctx, overlay)?;
    for entry in tree.entries() {
        validate_selection(entry, selections)?;
    }
    Ok(())
}

pub(crate) fn validate_selection(
    entry: &super::DesiredEntry,
    selections: &[PathBuf],
) -> Result<()> {
    let mut generated = BTreeMap::new();
    if let super::MaterializationIntent::RenderedFile(file) = &entry.intent {
        generated.insert(entry.target.clone(), file.source.clone());
    }
    if entry.intent.is_virtual_checkout() {
        if let Some(inventory) = entry.intent.checkout_scope().rendered {
            generated.extend(
                inventory
                    .iter()
                    .filter(|(_, file)| file.generated)
                    .map(|(path, file)| (entry.target.join(path), file.source.clone())),
            );
        }
        if let Some(record) = crate::materialize::virtual_checkout::state::record_for_entry(entry)?
            && let Some(state) = record.generated
        {
            generated.extend(
                state
                    .sources
                    .into_iter()
                    .map(|(path, source)| (entry.target.join(path), source)),
            );
        }
    }
    for (destination, source) in generated {
        ensure!(
            !selections
                .iter()
                .any(|selection| destination == *selection || destination.starts_with(selection)),
            "generated destination '{}' cannot be written back as source; edit source template '{}' instead",
            destination.display(),
            source.display()
        );
    }
    Ok(())
}

pub(crate) fn transform(
    ctx: &Context,
    overlay: &Overlay,
    relative: &Path,
    bytes: &[u8],
    mode: i32,
) -> Result<(PathBuf, RenderedFile)> {
    let policy = crate::overlays::rules::resolve_with_origins(overlay, relative, false);
    if !policy.template && !policy.strip_extension {
        return Ok((
            relative.to_path_buf(),
            RenderedFile {
                protection: Default::default(),
                source_revision: None,
                source: overlay.root.join(relative),
                bytes: bytes.to_vec().into(),
                identity: git2::Oid::hash_object(git2::ObjectType::Blob, bytes)?.to_string(),
                mode,
                generated: false,
                permissions: None,
            },
        ));
    }
    ensure!(
        matches!(mode, 0o100644 | 0o100755),
        "templates require ordinary regular source files"
    );
    let mode = policy.permissions.map_or(mode, |permissions| {
        if permissions.bits() & 0o111 != 0 {
            0o100755
        } else {
            0o100644
        }
    });
    let mut destination = relative.to_path_buf();
    if policy.strip_extension
        && let Some(extension) = destination.extension()
    {
        let literal = if policy.template {
            let name = destination
                .file_name()
                .and_then(|name| name.to_str())
                .context("template path is not valid UTF-8")?;
            literal_suffix(name, name.len() - extension.len() - 1)
        } else {
            true
        };
        if literal {
            destination.set_extension("");
        }
    }
    let output = if policy.template {
        let name = destination
            .to_str()
            .context("template path is not valid UTF-8")?;
        destination = PathBuf::from(templates::render_content(name, ctx)?);
        let text = std::str::from_utf8(bytes).context("template source is not valid UTF-8")?;
        templates::render_content(text, ctx)?.into_bytes()
    } else {
        bytes.to_vec()
    };
    ensure!(
        !destination.as_os_str().is_empty()
            && destination
                .components()
                .all(|part| matches!(part, Component::Normal(name) if !name.to_str().is_some_and(|name| name.eq_ignore_ascii_case(".git")))),
        "rendered destination must be a safe relative path"
    );
    // Canonical JSON orders map keys; identity never persists the inputs themselves.
    let state = serde_json::to_value(templates::TemplateContext::new(ctx)?)?;
    // UI flags must not change artifact identity when the rendered result is identical.
    let inputs = serde_json::json!({"data": ctx.data, "machine": ctx.machine, "env": state["env"], "paths": state["paths"], "overlays": state["overlays"]});
    let fingerprint = serde_json::to_vec(&(
        &overlay.root,
        relative,
        bytes,
        inputs,
        &destination,
        &output,
        mode,
        policy.template,
        policy.strip_extension,
        policy.permissions,
    ))?;
    let identity = git2::Oid::hash_object(git2::ObjectType::Blob, &fingerprint)?.to_string();
    Ok((
        destination,
        RenderedFile {
            protection: Default::default(),
            source_revision: None,
            source: overlay.root.join(relative),
            bytes: output.into(),
            identity,
            mode,
            generated: policy.template || policy.strip_extension,
            permissions: policy.permissions,
        },
    ))
}

fn literal_suffix(name: &str, dot: usize) -> bool {
    let bytes = name.as_bytes();
    let mut cursor = 0;
    while cursor + 1 < bytes.len() {
        let (closing, comment) = match &bytes[cursor..cursor + 2] {
            b"{{" => (b"}}", false),
            b"{%" => (b"%}", false),
            b"{#" => (b"#}", true),
            _ => {
                cursor += 1;
                continue;
            }
        };
        cursor += 2;
        let mut quote = None;
        let mut closed = false;
        while cursor + 1 < bytes.len() {
            let byte = bytes[cursor];
            if !comment {
                if quote.is_some() && byte == b'\\' {
                    cursor += 2;
                    continue;
                }
                if quote == Some(byte) {
                    quote = None;
                    cursor += 1;
                    continue;
                }
                if quote.is_none() && matches!(byte, b'\'' | b'"') {
                    quote = Some(byte);
                    cursor += 1;
                    continue;
                }
            }
            if quote.is_none() && &bytes[cursor..cursor + 2] == closing {
                cursor += 2;
                closed = true;
                break;
            }
            cursor += 1;
        }
        // Property dots and dynamic suffixes belong to Jinja, not Path::extension.
        if !closed || cursor > dot {
            return false;
        }
    }
    true
}

#[cfg(test)]
mod tests {
    use super::*;
    use assert_fs::prelude::*;
    use rstest::rstest;

    #[rstest]
    #[case("settings.dotfile", "settings")]
    #[case("settings", "settings")]
    #[case(".dotfile", ".dotfile")]
    #[case("settings.toml.jinja", "settings.toml")]
    #[case("{{ machine.os }}.jinja", std::env::consts::OS)]
    #[case("{{ machine.os }}", std::env::consts::OS)]
    #[case("{{ 'host.example' }}", "host.example")]
    #[case("{{ 'x}}.name' }}.jinja", "x}}.name")]
    #[case("{% if true %}{{ machine.os }}{% endif %}", std::env::consts::OS)]
    #[case("host{# .ignored #}", "host")]
    fn explicit_rules_render_arbitrary_filenames_and_strip_only_the_last_suffix(
        #[case] name: &str,
        #[case] expected: &str,
    ) {
        let temp = assert_fs::TempDir::new().unwrap();
        temp.child("over.yaml")
            .write_str("rules:\n  - {path: '**', template: true, strip_extension: true}\n")
            .unwrap();
        let repository = crate::overlays::Repository::new(temp.path().into());
        let overlay = repository.get("").unwrap();
        let ctx = Context::builder().repository(repository).build();
        let (destination, file) = transform(
            &ctx,
            &overlay,
            Path::new(name),
            b"{{ machine.os }}",
            0o100644,
        )
        .unwrap();
        assert_eq!(destination, Path::new(expected));
        assert_eq!(file.bytes.as_ref(), std::env::consts::OS.as_bytes());
    }

    #[test]
    fn independent_false_assignments_override_inherited_template_rules() {
        let temp = assert_fs::TempDir::new().unwrap();
        temp.child("over.yaml")
            .write_str("rules:\n  - {path: '**', template: true, strip_extension: true}\n")
            .unwrap();
        temp.child("app/over.yaml").write_str("rules:\n  - {path: '**', template: false}\n  - {path: literal.jinja, strip_extension: false}\n").unwrap();
        let repository = crate::overlays::Repository::new(temp.path().into());
        let overlay = repository.get("app").unwrap();
        let ctx = Context::builder().repository(repository).build();
        for (name, expected) in [("literal.jinja", "literal.jinja"), ("strip.jinja", "strip")] {
            let (destination, file) =
                transform(&ctx, &overlay, Path::new(name), b"{{ missing }}", 0o100644).unwrap();
            assert_eq!(destination, Path::new(expected));
            assert_eq!(file.bytes.as_ref(), b"{{ missing }}");
        }
    }

    #[test]
    fn rendering_errors_and_debug_output_do_not_disclose_template_values() {
        let temp = assert_fs::TempDir::new().unwrap();
        temp.child("over.yaml").write_str("data: {private: PRIVATE_RENDER_SENTINEL}\nrules:\n  - {path: '**', template: true}\n").unwrap();
        temp.child("config")
            .write_str("{{ data.private }}{{ missing }}")
            .unwrap();
        let repository = crate::overlays::Repository::new(temp.path().into());
        let overlay = repository.get("").unwrap();
        let ctx = Context::builder()
            .repository(repository)
            .overlay(overlay.clone())
            .root(temp.path().join("target"))
            .build()
            .resolve_data()
            .unwrap();
        let error = super::super::DesiredTree::build(&ctx, &overlay).unwrap_err();
        assert!(!format!("{error:#?}").contains("PRIVATE_RENDER_SENTINEL"));
        assert!(!format!("{ctx:?}").contains("PRIVATE_RENDER_SENTINEL"));
        temp.child("config")
            .write_str("{{ data.private }}")
            .unwrap();
        let tree = super::super::DesiredTree::build(&ctx, &overlay).unwrap();
        assert!(!format!("{tree:?}").contains("PRIVATE_RENDER_SENTINEL"));
    }
}
